if(s.profile.marital==='single'&&['all','during'].includes(s.tax.maritalDuringYear))out.push('สถานภาพปัจจุบันกับสถานภาพปีภาษีไม่ตรงกัน โปรดตรวจข้อมูล');
if(s.incomes.some(r=>r.taxSource==='estimate'&&r.amountMode!=='gross'))out.push('ประมาณภาษีจากยอดสุทธิไม่ได้: เลือกก่อนหัก หรือใช้ยอดตามหนังสือรับรอง');
if(s.incomes.some(r=>r.salaryId&&!bonusParent(s,r)))out.push('โบนัสยังไม่เชื่อมกับเงินเดือนที่ถูกต้อง ยอดภาษีจึงคิดแยก');
if(s.incomes.some(r=>r.frequency==='monthly'&&r.endMonth<r.startMonth))out.push('เดือนสิ้นสุดรายรับต้องไม่ก่อนเดือนเริ่ม');
