if(s.incomes.some(r=>r.taxInclude&&r.taxType==='8'&&r.method!=='actual'&&![0,60].includes(r.rate)))out.push('เงินได้ 40(8) มีอัตราเหมาที่ต้องตรวจเฉพาะกิจการ โดยเฉพาะนักแสดงซึ่งมีสูตรแยก');
